        id="bulk-reassign-to"
  }

  /** Settle the selected claims together: the server settles each it can, in list order, by the
   *  rules of settling one (a clerk's above the limit goes PENDING), and refuses the rest. */
  protected async bulkSettle(): Promise<void> {
    this.bulkSettleResult.set(null);
    this.bulkSettleError.set(null);
    const sheet = this.session.sheet();
    const ids = [...this.selectedClaims()];
    try {
      const done = await firstValueFrom(
        this.http.post<{ settled: number; refused: number; claims: Claim[] }>('/api/claims/bulk-settle', {
          sheet,
          user: this.session.user(),
          ids,
        }),
      );
      if (this.session.sheet() !== sheet) return;
      const byId = new Map(done.claims.map((c) => [c.id, c]));
      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
      this.selectedClaims.set(new Set());
      this.bulkSettleResult.set({ settled: done.settled, refused: done.refused });
    } catch {
      if (this.session.sheet() !== sheet) return;
      this.bulkSettleError.set('Could not settle the selected claims.');
    }
  }

  /** Move the selected claims to the chosen person together: the server moves each it can, in list
   *  order, by the rules of moving one, and refuses the rest, leaving them as they are. */
  protected async bulkReassign(): Promise<void> {
  tags: string[];
  /** The date the claim is due by, fixed when it was added. */
  dueBy: string;
  /** The claim's status log, oldest first: who moved it to each status, on the sheet's today then,
   *  with its due as computed at that moment. */
  log: ClaimLogLine[];
  /** The date the claim is deferred until; null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs the claim has. */
  proofs: number;
  /** The number of the claim this claim was split off from; null for a claim not made by a split. */
  splitFrom: string | null;
  /** The user whose open editor locks the claim for everyone else; null when unlocked. */
  lockedBy: string | null;
  /** Whether the claim was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  /** The last sheet-today a reminder was written for the claim; null when never reminded. */
  remindedOn: string | null;
  /** The reason the claim was voided with, from the sheet's void reasons; null when none. */
  voidReason: string | null;
  /** The claim's comments, oldest first. */
  comments: ClaimCommentLine[];
}

/** One comment on a claim: who wrote it, on the sheet's today then. */
export interface ClaimCommentLine {
  by: string;
  date: string;
  text: string;
}

